// node src/sim/build-results.ts
// Assembles RESULTS.md from the files the experiments wrote to sim-out/, so
// the published tables are exactly what the scripts measured.

import { existsSync, readdirSync, readFileSync, writeFileSync } from 'node:fs';

const read = (p: string) => (existsSync(p) ? readFileSync(p, 'utf8').trim() : null);
const parts: string[] = [];
parts.push('# Ghost Channel: measured results');
parts.push('');
parts.push(
  'Generated by `node src/sim/build-results.ts` from the output of the experiment scripts. **Everything in this file comes from the simulator or from a real video codec on a desktop. None of it was measured with a physical phone pointed at a physical screen.** The README says what that leaves open.',
);
parts.push('');

const model = read('sim-out/model.md');
if (model) {
  parts.push('## 1. Carrier choice (`npm run sim:model`)');
  parts.push('');
  parts.push(model.replace(/^## /gm, '### '));
  parts.push('');
}

interface Trial {
  decoded: boolean;
  payloadOk: boolean;
  tDecode: number | null;
  trueBer: number | null;
  packetsOk: number;
  packetsBad: number;
  nominalBps: number;
}
interface Cell {
  row: string;
  col: string;
  trials: Trial[];
}

// Sweep results may come from several processes (one per preset). Merge them
// per content type; the first result for a (row, column) pair wins.
const sweepFiles = existsSync('sim-out') ? readdirSync('sim-out').filter((f) => /^sweep-[a-z]+-[a-z]+\.json$/.test(f)).sort() : [];
const byContent = new Map<string, Map<string, Cell>>();
const colOrder: string[] = [];
for (const f of sweepFiles) {
  const content = f.replace(/^sweep-[a-z]+-/, '').replace('.json', '');
  const cells = JSON.parse(readFileSync('sim-out/' + f, 'utf8')) as Cell[];
  const map = byContent.get(content) ?? new Map<string, Cell>();
  for (const c of cells) {
    if (!colOrder.includes(c.col)) colOrder.push(c.col);
    const key = c.row + '|' + c.col;
    if (!map.has(key)) map.set(key, c);
  }
  byContent.set(content, map);
}

function cellText(c: Cell | undefined): string {
  if (!c) return 'not run';
  const n = c.trials.length;
  const ok = c.trials.filter((t) => t.decoded && t.payloadOk).length;
  const bers = c.trials.map((t) => t.trueBer).filter((b): b is number => b !== null && !Number.isNaN(b));
  const ber = bers.length ? bers.reduce((a, b) => a + b, 0) / bers.length : null;
  const berText = ber === null ? 'n/a' : ber < 1e-5 ? '0' : ber.toExponential(0);
  const pkOk = c.trials.reduce((a, t) => a + t.packetsOk, 0);
  const pkAll = pkOk + c.trials.reduce((a, t) => a + t.packetsBad, 0);
  if (ok === 0) return `**fail** · BER ${berText}`;
  const times = c.trials.filter((t) => t.tDecode !== null).map((t) => t.tDecode!);
  const time = times.reduce((a, b) => a + b, 0) / times.length;
  const bps = pkAll ? (c.trials[0].nominalBps * pkOk) / pkAll : 0;
  return `${ok}/${n} · ${time.toFixed(1)} s · BER ${berText} · ${pkOk}/${pkAll} pkts · ${Math.round(bps)} bps`;
}

if (byContent.size) {
  parts.push('## 2. Simulated camera sweep (`npm run sim:sweep`)');
  parts.push('');
  parts.push(
    'Simulated camera: 640×360 at 30 fps, 1/100 s exposure, 20 ms rolling-shutter readout, lens blur σ 0.8 px, noise 1.5 code values at mid-grey, 2 % auto-exposure drift, 120 ppm clock error, 0.5 ms timestamp jitter. Display: 60 Hz, scanned over 90 % of the frame period, 15 % carry-over from the previous frame. "0.4 m" means the screen is 1.33 screen-widths away (a 30 cm wide laptop panel at 40 cm); "1 m" is 3.33 and "2 m" is 6.67. The 720p columns use a 1280×720 camera with blur σ 1.3 px and noise 2.4 code values.',
  );
  parts.push('');
  parts.push(
    'Each cell: `trials decoded · time from first camera frame to the complete 60-byte payload · raw bit error rate before error correction, against ground truth · packets that passed CRC / packets attempted · throughput`. Throughput is the preset\'s net rate times that packet fraction. A trial stops as soon as the payload is complete, so it sees only a handful of packets and the throughput figure is coarse; section 3 has the long-run rate. **fail** means the payload was not recovered within 9 s. One trial per cell: a single cell is an indication, not a rate.',
  );
  parts.push('');
  const presetOrder = ['far', 'standard', 'dense'];
  for (const [content, map] of [...byContent.entries()].sort()) {
    const rows: string[] = [];
    for (const key of map.keys()) {
      const r = key.split('|')[0];
      if (!rows.includes(r)) rows.push(r);
    }
    rows.sort((a, b) => presetOrder.indexOf(a.split(' ')[0]) - presetOrder.indexOf(b.split(' ')[0]));
    parts.push(`### Content: ${content === 'talking' ? 'talking-head stand-in (mid-tones, slow motion)' : content === 'slide' ? 'white slide with dark text' : content}`);
    parts.push('');
    parts.push('| preset, axis, amplitude | ' + colOrder.join(' | ') + ' |');
    parts.push('|' + '---|'.repeat(colOrder.length + 1));
    for (const r of rows) parts.push(`| ${r} | ` + colOrder.map((c) => cellText(map.get(r + '|' + c))).join(' | ') + ' |');
    parts.push('');
    // Tally, for the README summary.
    let decoded = 0;
    let total = 0;
    for (const c of map.values()) {
      total += c.trials.length;
      decoded += c.trials.filter((t) => t.decoded && t.payloadOk).length;
    }
    const wrong = [...map.values()].flatMap((c) => c.trials).filter((t) => t.decoded && !t.payloadOk).length;
    parts.push(`${decoded} of ${total} trials recovered the payload; ${wrong} delivered a payload that differed from what was sent.`);
    parts.push('');
  }
}

const joins = existsSync('sim-out') ? readdirSync('sim-out').filter((f) => /^join-.*\.md$/.test(f)).sort() : [];
if (joins.length) {
  parts.push('## 3. Join anytime (`npm run sim:join`)');
  parts.push('');
  parts.push('A file is broadcast on a loop. The receiver starts at a random point in the symbol, the packet and the fountain sequence, at 0.4 m, colour axis at 4 %, talking-head content, 640×360 camera at 30 fps.');
  parts.push('');
  for (const f of joins) {
    parts.push(read('sim-out/' + f)!);
    parts.push('');
  }
}

const codec = read('sim-out/codec.md');
if (codec) {
  parts.push('## 4. Real video codecs (`npm run sim:codec`)');
  parts.push('');
  parts.push('Sender frames from the reference renderer, compressed and decompressed by ffmpeg (libx264, libvpx-vp9), then decoded by the real receiver with no camera in between. This isolates what compression does; filming the compressed video would add camera loss on top.');
  parts.push('');
  parts.push(codec);
  parts.push('');
}

const micro = read('sim-out/micro.md');
if (micro) {
  parts.push('## 5. Fountain overhead and pilot-check chance level (`npm run sim:micro`)');
  parts.push('');
  parts.push(micro);
  parts.push('');
}

const extra = read('sim-out/extra.md');
if (extra) {
  parts.push('## 6. Individual runs quoted in the README');
  parts.push('');
  parts.push(extra);
  parts.push('');
}
writeFileSync('RESULTS.md', parts.join('\n'));
console.log('RESULTS.md written');
